{"begin":"BEGIN_FSV-B19_repair_MAIN","stage":"repair","output":{"status":"READY","rego":"package external_pilot

import rego.v1

default allow := false

allow if {
    not blocked_from_purchase_order
}

blocked_from_purchase_order if {
    input.trusted.supplierOnHold == true
    not input.trusted.holdType == "Payments"
}","reason":"Source VIS-FSV-B19-01 section 2.4 states that when a supplier is blocked with hold type 'Invoices' or 'All', ERPNext will not allow Purchase Orders to be created. It also states that if a hold type is not selected, ERPNext defaults to 'All'. Therefore, a Purchase Order creation request must be denied when trusted.supplierOnHold is true unless the trusted.holdType is strictly 'Payments'."},"end":"END_FSV-B19_repair_MAIN"}
